<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/includes/helpers.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/booking.php';
require_login(); $resource_id = (int) ($_SESSION['booking']['resource_id'] ?? 0); $statement = db()->prepare('SELECT * FROM resources WHERE id = ? AND is_active = 1'); $statement->execute([$resource_id]); $resource = $statement->fetch(); if (!$resource) { redirect('booking-step-1.php'); }
$date = (string) ($_POST['booking_date'] ?? $_SESSION['booking']['booking_date'] ?? date('Y-m-d')); $selected_slots = (array) ($_POST['start_times'] ?? $_SESSION['booking']['start_times'] ?? []); $selected_slots = array_values(array_unique(array_map('strval', $selected_slots))); $occupied = valid_date($date) ? occupied_slots($resource_id, $date) : [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $valid_slots = array_keys(slot_options()); $invalid_selection = !$selected_slots || array_diff($selected_slots, $valid_slots); $unavailable = array_intersect($selected_slots, occupied_slots($resource_id, $date)); if (!valid_date($date) || $invalid_selection || $unavailable) { flash('danger', $unavailable ? 'Mindestens einer der ausgewählten Zeitslots ist inzwischen belegt.' : 'Bitte wählen Sie ein gültiges zukünftiges Datum und mindestens einen Zeitslot.'); } else { sort($selected_slots); $_SESSION['booking']['booking_date'] = $date; $_SESSION['booking']['start_times'] = $selected_slots; redirect('booking-step-3.php'); } }
$page_title = 'Datum und Zeitslot'; require __DIR__ . '/includes/header.php';
?><p class="step-indicator">Schritt 2 von 4 · <?= e($resource['name']) ?></p><h1>Datum und Zeitslots</h1><form method="post" class="form-panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="mb-4"><label class="form-label" for="booking_date">Datum</label><input class="form-control" id="booking_date" name="booking_date" type="date" min="<?= e(date('Y-m-d')) ?>" value="<?= e($date) ?>" required><button class="btn btn-outline-primary mt-2" type="button" onclick="this.form.submit()">Verfügbarkeit anzeigen</button></div><fieldset><legend class="h5">Feste Zeitslots</legend><p class="text-muted">Sie können mehrere verfügbare Slots auswählen.</p><?php foreach (slot_options() as $start => $end): $is_occupied = in_array($start, $occupied, true); ?><label class="d-block border rounded p-3 mb-2 <?= $is_occupied ? 'text-muted bg-light' : '' ?>"><input type="checkbox" name="start_times[]" value="<?= e($start) ?>" <?= in_array($start, $selected_slots, true) ? 'checked' : '' ?> <?= $is_occupied ? 'disabled' : '' ?>> <?= e($start) ?> bis <?= e($end) ?> <?php if ($is_occupied): ?><span class="badge text-bg-secondary">belegt</span><?php else: ?><span class="badge text-bg-success">verfügbar</span><?php endif; ?></label><?php endforeach; ?></fieldset><button class="btn btn-primary mt-3" type="submit">Extras auswählen</button></form>
<?php require __DIR__ . '/includes/footer.php';